import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>ছবি 100KB-তে ছোট করতে হবে, কিন্তু কোয়ালিটি ধরে রাখতে চান? এই ধাপে ধাপে গাইডে আপনি শিখবেন কীভাবে সিভি, ব্লগ আর ইমেইলের জন্য পরিষ্কার 100KB ছবি বানাবেন৤</p>\n<p>প্রক্রিয়াটি সহজ, তবে কয়েকটি ছোট সিদ্ধান্ত ফলের মান অনেক বদলে দেয়৤ সঠিক মূল ফাইল, সঠিক ফরম্যাট আর একটু যাচাই — এই তিনটিই মূল বিষয়৤</p>\n<p>শুরু থেকে শেষ পর্যন্ত প্রতিটি ধাপ এখানে দেওয়া হলো, সঙ্গে সাধারণ সমস্যার সমাধানও আছে৤</p>\n<h2 id=\"what-you-need\">যা যা দরকার</h2>\n<p>আপনার দরকার মূল ছবিটি, একটি ব্রাউজার আর কয়েক মিনিট সময়৤ কোনো অ্যাপ ইনস্টল করতে হয় না৤</p>\n<p>100KB করতে মূল ছবিটা যত ভালো হবে, ফল তত ভালো হবে৤ ক্যামেরার আসল ছবি বা উচ্চ মানের স্ক্যান ব্যবহার করুন, আর হোয়াটসঅ্যাপ থেকে পাওয়া ছবি এড়িয়ে চলুন৤</p>\n<p>পোর্টালের নিয়ম থাকলে তা হাতের কাছে রাখুন৤ আকার, ফরম্যাট আর মাপের নিয়ম আগেই জেনে নিলে পরে ঝামেলা হয় না৤</p>\n<h2 id=\"step-1-open-the-tool\">ধাপ ১: টুলটি খুলুন</h2>\n<p>ব্রাউজারে <a href=\"/bn/image-100kb-te-compress-korun\">100KB-তে ছবি কমপ্রেস করার টুলটি</a> খুলুন৤ পাতাটি লোড হলেই আপলোড এলাকা দেখতে পাবেন৤</p>\n<p>ফোনে হলে বোতামটি বড় দেখায়, যাতে ট্যাপ করা সহজ হয়৤ ডেস্কটপে ছবি টেনে ছেড়ে দেওয়া যায়৤</p>\n<p>টুলটি আপনার ডিভাইসেই চলে, তাই ছবি কোথাও আপলোড হয় না৤ ব্যক্তিগত ছবির জন্যও এটি নিরাপদ৤</p>\n<h2 id=\"step-2-upload\">ধাপ ২: ছবি আপলোড করুন</h2>\n<p>100KB টুলের আপলোড জায়গায় ছবি টেনে ছাড়ুন, অথবা বোতামে ট্যাপ করে গ্যালারি খুলুন৤ JPG, PNG, WebP আর HEIC—চার ফরম্যাটই 100KB লক্ষ্যে নেওয়া হয়৤</p>\n<p>25MB পর্যন্ত ফাইল চলে, তাই ফোনের ক্যামেরার বড় ছবিও সরাসরি দেওয়া যায়৤ 100KB-তে নামানোর আগে ছবি ছোট করার দরকার নেই৤</p>\n<p>ভুল ছবি উঠে গেলে পাতা না বদলে আবার বেছে নিন৤ সঠিক ছবি না আসা পর্যন্ত 100KB-র সার্চ শুরু হয় না, তাই তাড়াহুড়ো করবেন না৤</p>\n<h2 id=\"step-3-choose-format\">ধাপ ৩: ফরম্যাট বেছে নিন</h2>\n<p>ছবির জন্য JPG বেছে নিন৤ এটি সব জায়গায় গ্রহণযোগ্য আর ত্বকের রং মসৃণ রাখে৤</p>\n<p>পোর্টাল WebP নিলে WebP বেছে নিতে পারেন৤ একই আকারে এটি একটু বেশি বিবরণ ধরে রাখে৤</p>\n<p>লোগো বা লেখার ছবি হলে PNG রাখুন৤ তবে ছবির ক্ষেত্রে PNG এড়িয়ে চলুন, কারণ এটি 100KB-তে আঁটতে চায় না৤</p>\n<p>ফরম্যাট বেছে নেওয়ার সময় ছবির ধরন দেখুন৤ ছবিতে মানুষ, প্রকৃতি বা খাবার থাকলে JPG ভালো৤ লেখা, লোগো বা গ্রাফিক্স থাকলে PNG বা WebP ভালো ফল দেয়৤ ভুল ফরম্যাটে ফাইল বড় হয়৤</p>\n<p>পোর্টালের নিয়মে নির্দিষ্ট ফরম্যাট থাকলে সেটিই বেছে নিন৤ কিছু পোর্টাল শুধু JPG নেয়, কিছু PNG-ও নেয়৤ নিয়ম না মেনে WebP পাঠালে ফাইল ফিরে আসতে পারে৤</p>\n<p>WebP বেছে নিলে ফাইল প্রায়ই সবচেয়ে ছোট হয়৤ তবে পুরোনো সফটওয়্যার WebP খুলতে পারে না৤ প্রাপকের সফটওয়্যার নতুন হলে WebP নিরাপদ, না হলে JPG বেছে নিন৤</p>\n<p>PNG থেকে JPG-তে বদলালে স্বচ্ছ ব্যাকগ্রাউন্ড সাদা হয়ে যায়৤ লোগো বা স্টিকারে এটি সমস্যা তৈরি করে৤ স্বচ্ছতা দরকার হলে PNG বা WebP-তেই থাকুন৤</p>\n<p>ফরম্যাট বদলানোর পর প্রিভিউ দেখে নিন৤ JPG-তে লেখার ধার কিছুটা নরম হতে পারে, আর PNG-তে ছবির রং বদলাতে পারে না৤ প্রিভিউতে সমস্যা দেখলে ফরম্যাট বদলে আবার চালান৤</p>\n<p>একই ছবি তিনটি ফরম্যাটে কমপ্রেস করে তুলনা করুন৤ টুলটি প্রতিটি ফরম্যাটে আলাদা ফল দেয়, আর সবচেয়ে ছোট ফাইলটিই সবসময় সবচেয়ে পরিষ্কার হয় না৤ চোখে দেখে সিদ্ধান্ত নিন৤</p>\n<p>HEIC ছবি আপলোড করলে আউটপুট ফরম্যাট JPG বেছে নেওয়া ভালো৤ HEIC থেকে সরাসরি JPG করলে পোর্টালে গ্রহণযোগ্য ফাইল পাওয়া যায়৤ আলাদা কনভার্টের ধাপ দরকার হয় না৤</p>\n<p>ফরম্যাট বেছে নেওয়ার সময় ভবিষ্যতের ব্যবহার ভাবুন৤ ছবিটি পরে সম্পাদনা করার পরিকল্পনা থাকলে PNG বা মূল ফাইল রাখুন৤ শুধু পাঠানোর জন্য JPG যথেষ্ট৤</p>\n<p>ফরম্যাটের পছন্দ ফাইলের আকারের চেয়ে মানের উপর বেশি প্রভাব ফেলে৤ সঠিক ফরম্যাটে ১০০KB ছবি ভুল ফরম্যাটের ২০০KB ছবির চেয়ে পরিষ্কার দেখাতে পারে৤ তাই ফরম্যাটকে হালকাভাবে নেবেন না৤</p>\n<h2 id=\"step-4-run-compression\">ধাপ ৪: কমপ্রেশন চালান</h2>\n<p>ফরম্যাট বেছে নিলেই টুল সার্চ শুরু করে৤ এটি এমন কোয়ালিটি খোঁজে যা 100KB-এর নিচে থাকে, কিন্তু যতটা সম্ভব বেশি৤</p>\n<p>100KB-র বাইনারি সার্চ কয়েক সেকেন্ডে শেষ হয়, আর কোয়ালিটির সংখ্যা আপনাকে বসাতে হয় না৤ টুল নিজেই 100KB-র নিচে থাকা সেরা মান খুঁজে নেয়৤</p>\n<p>ফল এলে মূল আর নতুন আকার দুটোই দেখা যায়৤ কত শতাংশ কমল তা দেখে বুঝতে পারবেন কাজ ঠিকমতো হয়েছে কি না৤</p>\n<h2 id=\"step-5-preview\">ধাপ ৫: ফল দেখে নিন</h2>\n<p>100KB-তে নামানোর আগে প্রিভিউতে ছবি জুম করে দেখুন৤ মুখ, চোখ আর ছোট লেখায় নজর দিন, কারণ এই তিন জায়গায় ক্ষতি প্রথমে ধরা পড়ে৤</p>\n<p>ছবি সামগ্রিকভাবে ঠিক লাগলে তবেই ডাউনলোড করুন৤ দেখানোর আকারে ছোট নরমভাব চোখে পড়ে না, তবে পুরো আকারে দেখা যায়৤</p>\n<p>কোনো অংশ অস্পষ্ট মনে হলে ফরম্যাট বদলে 100KB-তে আবার চেষ্টা করুন৤ JPG থেকে WebP-তে গেলে অনেক সময় একই আকারে ফল ভালো হয়৤</p>\n<h2 id=\"step-6-download\">ধাপ ৬: ডাউনলোড করুন</h2>\n<p>ফলে খুশি হলে ডাউনলোড বোতাম চাপুন৤ ফোনে ফাইল ডাউনলোড ফোল্ডারে যাবে, আর ডেস্কটপে ডাউনলোডের জায়গায়৤</p>\n<p>নাম বদলে নিন, যেমন resume-photo-100kb.jpg৤ এতে পরে ফরমে খুঁজে পাওয়া সহজ হয়৤</p>\n<p>ফাইলটি খুলে আকার আর মাপ একবার দেখে নিন৤ সব ঠিক থাকলে তবেই আপলোড করুন৤</p>\n<h2 id=\"fixing-problems\">সমস্যা হলে কী করবেন</h2>\n<p>100KB না মিললে প্রথমে ফরম্যাট দেখুন৤ PNG-তে থাকলে JPG-তে বদলান, কারণ PNG ছবি 100KB-তে পৌঁছাতে পারে না৤</p>\n<p>এরপর ছবি টাইট ক্রপ করুন৤ অপ্রয়োজনীয় পটভূমি কেটে ফেললে 100KB-র লক্ষ্য মেলা সহজ হয়৤</p>\n<p>তাতেও না হলে মাপ একটু কমান৤ ছোট মাপে একই কোয়ালিটি কম বাজেটে ভালো দেখায়, আর মুখের ছবিতে পার্থক্য চোখে পড়ে না৤</p>\n<p>সমস্যা হলে প্রথমে ফাইলের আকার দেখুন৤ ২০MB-এর বেশি ফাইল টুলটি নাও নিতে পারে৤ বড় ফাইল প্রথমে একটু ছোট করে আবার আপলোড করুন৤</p>\n<p>সমস্যা হলে ব্রাউজার বদলে দেখুন৤ পুরোনো ব্রাউজারে টুলটি ঠিকমতো নাও চলতে পারে৤ ক্রোম বা ফায়ারফক্সের নতুন সংস্করণে চেষ্টা করুন৤</p>\n<p>সমস্যা হলে পাতাটি রিফ্রেশ করুন৤ রিফ্রেশ করলে টুলটি আবার লোড হয়৤ বেশিরভাগ ছোট সমস্যা রিফ্রেশে ঠিক হয়৤</p>\n<p>সমস্যা হলে ফরম্যাট বদলে দেখুন৤ PNG ছবি JPG-তে নিলে ফাইল ছোট হয়৤ WebP-তে নিলে আরও ছোট হয়৤ ফরম্যাট বদলে সমস্যা মিটতে পারে৤</p>\n<p>সমস্যা হলে ছবির মাপ কমান৤ ৪০০০ পিক্সেলের ছবি ১০০KB-তে আনা কঠিন৤ মাপ ১২০০ পিক্সেলে নামালে সমস্যা মিটে যায়৤</p>\n<p>সমস্যা হলে মূল ফাইল থেকে আবার শুরু করুন৤ একবার কমপ্রেস করা ফাইল আবার কমপ্রেস করলে মান কমে৤ মূল থেকে শুরু করলে ভালো ফল পাওয়া যায়৤</p>\n<p>সমস্যা হলে ইন্টারনেট সংযোগ দেখুন৤ টুলের পাতা লোড হতে ইন্টারনেট লাগে৤ সংযোগ ধীর হলে পাতা ঠিকমতো লোড হয় না৤</p>\n<p>সমস্যা হলে ফোনের ব্রাউজারে ডেস্কটপ মোড চেষ্টা করুন৤ কিছু টুল মোবাইল মোডে ঠিকমতো চলে না৤ ডেস্কটপ মোডে সব বোতাম দেখা যায়৤</p>\n<p>সমস্যা না মিটলে ছবিটি অন্য টুলে চেষ্টা করুন৤ এক টুলে না হলে অন্য টুলে হতে পারে৤ তবে প্রথমে এই টুলের সব সমাধান চেষ্টা করুন৤</p>\n<h2 id=\"resume-photo-workflow\">সিভির ছবির কাজের ধারা</h2>\n<p>সিভির ছবি তোলার সময় হালকা দেয়ালের সামনে দাঁড়ান৤ ভালো আলোয় তোলা ছবি কমপ্রেসের পরও পরিষ্কার থাকে৤</p>\n<p>মাথা ও কাঁধ পর্যন্ত ক্রপ করুন৤ সিভিতে ছবি ছোট দেখায়, তাই মুখ বড় রাখা জরুরি৤</p>\n<p>100KB-তে করে ফাইলটি সিভির ফোল্ডারে রাখুন৤ একই ছবি পরে লিংকডইনেও ব্যবহার করা যায়৤</p>\n<h2 id=\"blog-thumbnail-workflow\">ব্লগ থাম্বনেইলের কাজের ধারা</h2>\n<p>ব্লগের থাম্বনেইল যে আকারে দেখানো হবে, সেই মাপে ছবি রাখুন৤ বাড়তি মাপ শুধু ফাইল বড় করে৤</p>\n<p>থাম্বনেইলে লেখা থাকলে JPG-তে 100KB রাখুন৤ লেখা পড়া যায় কি না জুম করে দেখুন৤</p>\n<p>প্রতিটি পোস্টের থাম্বনেইল একইভাবে বানান৤ এতে ব্লগের চেহারা একরকম থাকে৤</p>\n<h2 id=\"phone-workflow\">ফোনে করার কাজের ধারা</h2>\n<p>ফোনে ব্রাউজার খুলে 100KB টুল চালান৤ গ্যালারি থেকে ছবি বেছে নেওয়া যায়, আর কমপ্রেস করে সঙ্গে সঙ্গে পোর্টালে আপলোড করা যায়৤</p>\n<p>আইফোনের HEIC ছবি 100KB টুল নিজেই সামলে নেয়৤ আলাদা কনভার্ট দরকার নেই, HEIC সরাসরি আপলোড করুন৤</p>\n<p>ডাউনলোড করা ফাইল ফাইল অ্যাপে পাবেন৤ সেখান থেকে সরাসরি পোর্টালে আপলোড করা যায়৤</p>\n<h2 id=\"certificate-scans\">সার্টিফিকেট স্ক্যান 100KB-তে করা</h2>\n<p>সার্টিফিকেট স্ক্যান করার সময় 300 DPI ব্যবহার করুন৤ এতে লেখা পরিষ্কার থাকে৤</p>\n<p>100KB-র জন্য সার্টিফিকেট কালো-সাদা মোডে স্ক্যান করলে ফাইল ছোট হয়৤ রঙিন সিল থাকলে রঙিন মোড রাখুন, নইলে সিলের রং হারিয়ে যায়৤</p>\n<p>স্ক্যানের চারপাশের অতিরিক্ত সাদা জায়গা কেটে ফেলুন৤ এতে ফাইল ছোট হয় আর লেখা বড় দেখায়৤</p>\n<h2 id=\"comparing-results\">ফল তুলনা করে দেখা</h2>\n<p>JPG আর WebP দুটি সংস্করণ বানিয়ে পাশাপাশি দেখুন৤ কোনটি পরিষ্কার দেখায় তা নিজেই বুঝতে পারবেন৤</p>\n<p>তুলনার সময় একই জায়গায় জুম করুন৤ মুখ বা লেখার অংশে পার্থক্য সবচেয়ে বেশি ধরা পড়ে৤</p>\n<p>যেটি ভালো দেখায় সেটি রাখুন, অন্যটি মুছে দিন৤ দুটি রাখলে পরে গুলিয়ে যেতে পারে৤</p>\n<p>ফলাফল তুলনা করার সময় মূল আর কমপ্রেস করা ছবি পাশাপাশি রাখুন৤ দুটি ছবি একই স্ক্রিনে দেখলে পার্থক্য ধরা পড়ে৤ আলাদা সময়ে দেখলে পার্থক্য মনে থাকে না৤</p>\n<p>ফলাফল তুলনা করার সময় ছবি জুম করুন৤ সাধারণ আকারে দুটি ছবি একই লাগতে পারে৤ ২০০ শতাংশ জুমে পার্থক্য স্পষ্ট হয়৤</p>\n<p>ফলাফল তুলনা করার সময় ফাইলের আকার দেখুন৤ কতটা ছোট হয়েছে তা হিসাব করুন৤ সঞ্চয় শতাংশে দেখুন৤</p>\n<p>ফলাফল তুলনা করার সময় লোডের সময় মাপুন৤ ছোট ফাইলের পাতা কত দ্রুত লোড হয় তা দেখুন৤ গতি বাড়লে ফল ভালো৤</p>\n<p>ফলাফল তুলনা করার সময় অন্য কাউকে দেখান৤ আপনি যে পার্থক্য দেখছেন তা অন্যরা নাও দেখতে পারে৤ দুজন মানুষের মত মিললে সিদ্ধান্ত নির্ভরযোগ্য হয়৤</p>\n<p>ফলাফল তুলনা করার পর সেরা সেটিংটি লিখে রাখুন৤ পরের ছবিতে একই সেটিং ব্যবহার করলে ফল একই থাকে৤ বারবার তুলনা করার দরকার হয় না৤</p>\n<p>ফলাফল তুলনা করার সময় মোবাইল আর কম্পিউটার দুটোতেই দেখুন৤ মোবাইলে পার্থক্য কম দেখা যায়৤ কম্পিউটারে পার্থক্য বেশি ধরা পড়ে৤</p>\n<p>ফলাফল তুলনা করার সময় লেখার দিকে মনোযোগ দিন৤ লেখাযুক্ত ছবিতে পার্থক্য বেশি ধরা পড়ে৤ লেখা পরিষ্কার থাকলে ফল ভালো৤</p>\n<p>ফলাফল তুলনা করার সময় ছবির রং দেখুন৤ রং বদলে গেলে সেটিং ঠিক নেই৤ রং ঠিক থাকলে ফল ভালো৤</p>\n<h2 id=\"auto-convert-png\">PNG স্বয়ংক্রিয়ভাবে কনভার্ট করা</h2>\n<p>PNG ছবি আপলোড করলে টুল অনেক সময় JPG-তে কনভার্ট করার পরামর্শ দেয়৤ ছবির ক্ষেত্রে এই পরামর্শ মেনে নিন৤</p>\n<p>তবে লোগো বা স্বচ্ছ ছবি হলে PNG-ই রাখুন৤ স্বচ্ছতা JPG-তে থাকে না৤</p>\n<p>কনভার্টের পর ফাইলের আকার দেখুন৤ ছবির ক্ষেত্রে আকার প্রায়ই অর্ধেকেরও কম হয়ে যায়৤</p>\n<h2 id=\"recompress-warning\">আবার কমপ্রেস করার সতর্কতা</h2>\n<p>100KB ফাইল আবার কমপ্রেস করবেন না৤ প্রতিবার কোয়ালিটি কমে, আর ছবি আরও নরম হয়৤</p>\n<p>ভিন্ন আকার দরকার হলে মূল ছবি থেকে আবার বানান৤ মূল ছবি সবসময় সংরক্ষণ করুন৤</p>\n<p>কেউ 100KB ফাইল পাঠালে সেটি মূল হিসেবে ব্যবহার করবেন না৤ আসল মূল ছবিটি চেয়ে নিন৤</p>\n<p>একবার কমপ্রেস করা ছবি আবার কমপ্রেস করবেন না৤ দ্বিতীয়বার মান অনেক কমে যায়৤ আকার খুব কমে না৤ মূল থেকে আবার করুন৤</p>\n<p>আবার কমপ্রেস করার সতর্কতা হলো ফাইলের আকার দেখা৤ ফাইল অস্বাভাবিক ছোট হলে মান কমেছে৤ আকার দেখে সতর্ক হোন৤</p>\n<p>আবার কমপ্রেস করলে লেখা নষ্ট হয়৤ ছোট অক্ষর দ্বিতীয়বারে ভেঙে যায়৤ লেখাযুক্ত ছবি আবার কমপ্রেস করবেন না৤</p>\n<p>আবার কমপ্রেস করলে রং বদলে যায়৤ প্রতিবার রং একটু একটু বদলায়৤ পণ্যের ছবি আবার কমপ্রেস করবেন না৤</p>\n<p>আবার কমপ্রেস করার আগে মূল ফাইল খুঁজুন৤ মূল থাকলে আবার করার দরকার নেই৤ মূল থেকে নতুন করে করুন৤</p>\n<p>আবার কমপ্রেস করার সতর্কতা হলো প্রিভিউ দেখা৤ প্রিভিউতে মান খারাপ লাগলে থামুন৤ মূল থেকে আবার শুরু করুন৤</p>\n<p>আবার কমপ্রেস করলে সময় নষ্ট হয়৤ দ্বিতীয়বারে ফল ভালো হয় না৤ সময় বাঁচাতে মূল থেকে করুন৤</p>\n<p>আবার কমপ্রেস করার ভুলটি নতুন ব্যবহারকারীরা বেশি করেন৤ অভিজ্ঞ ব্যবহারকারীরা মূল থেকে করেন৤ অভ্যাসটি শিখে নিন৤</p>\n<p>আবার কমপ্রেস করার সতর্কতা মনে রাখুন৤ এই একটি নিয়ম মানলে ছবির মান ঠিক থাকে৤ নিয়মটি নোট করে রাখুন৤</p>\n<h2 id=\"keeping-originals-safe\">মূল ছবি নিরাপদে রাখা</h2>\n<p>মূল ছবি আলাদা ফোল্ডারে রাখুন, যেমন Originals৤ কমপ্রেস করা ফাইল অন্য ফোল্ডারে রাখুন৤</p>\n<p>100KB ফাইলের ক্লাউড ব্যাকআপে নাম পরিষ্কার রাখুন৤ বছরখানেক পরেও যেন বোঝা যায় কোনটি মূল আর কোনটি কমপ্রেস করা৤</p>\n<p>ফোন বদলানোর সময় মূল ছবিগুলো আগে সরিয়ে নিন৤ কমপ্রেস করা ফাইল দিয়ে মূল ফেরানো যায় না৤</p>\n<h2 id=\"team-workflows\">দলের কাজে 100KB ব্যবহার</h2>\n<p>দলে কাজ করলে সবাই একই নিয়ম মানুন৤ ফরম্যাট, আকার আর নামের নিয়ম লিখে রাখুন৤</p>\n<p>একটি শেয়ার্ড ফোল্ডারে 100KB ছবিগুলো রাখুন৤ এতে সবাই একই ফাইল ব্যবহার করে৤</p>\n<p>নতুন সদস্য এলে নিয়মটি দেখিয়ে দিন৤ এতে ভুল ছবি আপলোড হওয়ার আশঙ্কা কমে৤</p>\n<h2 id=\"alt-text-seo\">Alt টেক্সট আর SEO</h2>\n<p>ওয়েবসাইটে ছবি আপলোড করলে alt টেক্সট যোগ করুন৤ এটি SEO-তে সাহায্য করে আর স্ক্রিন রিডার ব্যবহারকারীদের কাজে লাগে৤</p>\n<p>Alt টেক্সটে ছবিটি কী দেখায় তা সংক্ষেপে লিখুন৤ কীওয়ার্ড ভরবেন না৤</p>\n<p>ফাইলের নামেও বর্ণনামূলক শব্দ রাখুন৤ এতে সার্চ ইঞ্জিন ছবিটি ভালো বোঝে৤</p>\n<h2 id=\"measuring-improvement\">উন্নতি মাপা</h2>\n<p>কমপ্রেসের আগে আর পরে ফাইলের আকার লিখে রাখুন৤ কত শতাংশ কমল তা দেখে বুঝতে পারবেন কতটা লাভ হলো৤</p>\n<p>ওয়েবসাইটের গতি পরীক্ষা করুন৤ ছবি ছোট করলে পাতা কত দ্রুত লোড হয় তা দেখুন৤</p>\n<p>মাসে একবার পুরোনো ছবির ওজন পরীক্ষা করুন৤ বড় ছবি পেলে 100KB-তে করে নিন৤</p>\n<h2 id=\"rounding-note\">শেষ কথা: গোল সংখ্যা নিয়ে ভাববেন না</h2>\n<p>99KB বা 100KB — দুটোই ঠিক৤ সীমা 100KB হলে 99KB-এর নিচে থাকলেই হয়৤</p>\n<p>হুবহু 100KB মেলানোর চেষ্টা করবেন না৤ টুলের ব্যাজই যথেষ্ট নিশ্চয়তা দেয়৤</p>\n<p>মূল বিষয় হলো ছবি পরিষ্কার দেখানো আর ফাইল সীমার মধ্যে রাখা৤ এই দুটি হলেই কাজ শেষ৤</p>\n<p>পূর্ণ গাইডটি পড়ুন <a href=\"/bn/blog/image-100kb-te-compress-korun-guide\">100KB-তে ছবি কমপ্রেস করার সম্পূর্ণ গাইড</a> আর ফরম্যাট তুলনার জন্য দেখুন <a href=\"/bn/blog/100kb-image-quality-format\">100KB-তে JPG বনাম PNG বনাম WebP</a>৤ ছোট সীমার জন্য <a href=\"/bn/image-50kb-te-compress-korun\">50KB কমপ্রেসর</a> ব্যবহার করুন৤</p>\n";

